const common = 'Use case: stylized-concept. Create ONE finished original high quality game asset, not an asset sheet or collage. Medieval fantasy hand painted realism, crisp fine material detail, restrained elegant ornament, believable construction. Complete centered silhouette with at least 8% clear padding on all four edges. True alpha transparency outside the object. No background, floor, ground plane, cast shadow, ambient halo, checkerboard pattern, labels, text, UI, logo or watermark. No fragments or neighboring objects. ';
const housePrompt = (d) => common + 'Asset type: individual furniture token for House 2.0. Subject: ' + d + '. CRITICAL CAMERA: perfectly orthographic vertical view looking straight down 90 degrees, a horizontal architectural plan. Show ONLY horizontal TOP surfaces; vertical front and side faces, legs and undersides are hidden below the object. No isometric projection, perspective, three quarter angle or tilt. Parallel opposing edges, no taper. Use fully diffuse neutral overhead light; no painted shadows on or outside the object; retain intrinsic wood grain, seams, carving and material color. Fully visible complete object with realistic balanced proportions.';
const heraldPrompt = (kind,d) => common + 'Asset type: single layered guild crest ' + kind + '. Subject: ' + d + '. Frontal symmetric heraldic presentation, highly polished detailed fantasy RPG illustration, rich aged metal or woven textile workmanship. ' + (kind==='banner' ? 'The cloth hangs from an implied horizontal support; do not draw poles, metal frames, symbols, animals or central insignia. The broad central 60% of the textile remains plain for a separate emblem layer. Gentle natural fabric folds with even diffuse lighting.' : kind==='frame' ? 'ONLY the ornamental border, with the entire large inner 60% of the frame truly transparent and EMPTY. No cloth, background, shield fill, central symbol or badge. Frame must be one complete coherent object, finely resolved and bold enough at small sizes.' : 'Single sculpted heraldic emblem in antique ivory silver metal with warm gold accents and dark patina in fine recessed detail. No frame, shield, banner, backing plate or scenery. Strong legible coherent silhouette with detailed expressive anatomy or craftsmanship, integrated sculptural form.') + ' No projected shadow. At least 8% transparent margin around every extremity.';
const scenePrompt = (d) => 'Use case: stylized-concept. Create one finished original wide landscape 16:9 medieval fantasy roleplay environment background. Scene: ' + d + '. Beautifully detailed painterly realism, coherent perspective, rich grounded wood stone cloth and foliage textures, polished RPG environment art. Camera at standing eye height looking slightly down onto visible walkable ground for placing character cutouts. Furnishings and small objects occupy the CENTER and middle of the scene too; leave several open standing areas and lanes distributed among furniture, avoid a broad empty foreground. All furnishings are painted into this SINGLE coherent illustration, with consistent lighting and scale. Full opaque edge-to-edge background. No people, animals, characters, readable lettering, UI, logos, watermark or borders.';
if (furniture.length!==100 || banners.length!==20 || frames.length!==20 || symbols.length!==20) throw Error('Invalid counts '+[furniture.length,banners.length,frames.length,symbols.length]);
const jobs = [
 ...scenes.map(([id,name,d])=>({id:'rp-'+id,kind:'scene',key:id,name,image:'/rp-lobby/20261019-integrated/'+id+'.webp',prompt:scenePrompt(d),transparent:false})),
 ...furniture.map(([name,category,width,height,d],i)=>({id:'house2-new-'+String(i+1).padStart(3,'0'),kind:'house2',name,category,width,height,image:'/house2/expansion-20261019/'+String(i+1).padStart(3,'0')+'.webp',prompt:housePrompt(d),transparent:true})),
 ...[['banner',banners],['frame',frames],['symbol',symbols]].flatMap(([kind,rows])=>rows.map(([key,name,d])=>({id:'crest-'+key,kind,key,name,image:'/guild/crests-expansion-20261019/'+key+'.webp',prompt:heraldPrompt(kind,d),transparent:true}))),
];
await fs.mkdir('.local/asset-expansion-20261019/results',{recursive:true});
await fs.mkdir('.local/asset-expansion-20261019/originals',{recursive:true});
await fs.writeFile('data/asset-expansion-20261019.json',JSON.stringify({method:'built-in image_gen, one call per asset',jobs},null,2)+'\n');
console.log({jobs:jobs.length,house2:furniture.length,banners:banners.length,frames:frames.length,symbols:symbols.length,scenes:scenes.length});
